INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816664992', 'Fernanda', 'Cierre', 'HB20', '', NULL, 'Cliente Fernanda, de Tucumán Capital, llegó por un anuncio general de AGN Hyundai. Será atendida por llamada o mensaje desde la sucursal de Salta. Confirmó que reciben usados como parte de pago y detalló que tiene un Ford Fiesta 2017 Se Plus para entregar. Definió su interés en el HB20 versión Comfort Plus, se le envió la imagen principal del modelo. Preguntó por precio de la versión Comfort Plus; se le explicó que el valor exacto lo confirma un asesor según versión y permuta. Pidió ser contactada por WhatsApp/mensaje, se confirma que un asesor la contacta por esa vía a la brevedad.', '2026-08-10T16:50:02.040571+00:00', '2026-08-10T19:57:35.398239+00:00', '', '', 'Tucumán', 'Capital', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', 'Comfort Plus', '', 'Permuta', '', 'false', '', 'Ford Fiesta 2017 Se Plus', '2026-08-10 16:57');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874732132', '', 'Desarrollada', 'Staria', '', NULL, 'El cliente preguntó por la Staria Ultimate 4WD, se le mostraron imágenes principal e interior. Luego pidió ver el catálogo completo y se le envió la imagen general con todos los modelos, ofreciendo el link web. Se le preguntó uso previsto. En este turno el cliente solo saludó nuevamente; se le repreguntó el nombre para continuar la charla.', '2026-07-16T14:57:08.33376+00:00', '2026-08-03T13:43:35.537667+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/destacados_garantia.jpg:principal, https://agnhyundai.com.ar/wp-content/uploads/2025/07/destacados_garantia.jpg:interior, https://agnhyundai.com.ar/wp-content/uploads/2026/07/Nuestros-Vehiculos.png:catalogo', 'Ultimate 4WD', '', '', '', 'false', '', '', NULL);
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875907960', 'Facundo', 'Cierre', 'Tucson', '', NULL, 'Cliente llegó por anuncio de Hyundai Tucson Safety (paquete SmartSense ADAS). Se envió imagen principal de Tucson. Cliente se identificó como Facundo, confirmó que es de Salta capital. Facundo indicó que todavía no quiere ir presencialmente y confirmó que prefiere ser contactado por mensaje en vez de visita presencial o llamada. Confirmó explícitamente que se coordine el contacto por mensaje. Falta capturar apellido, ciudad puntual, horario preferido y necesidades del cliente (uso previsto).', '2026-08-06T16:17:01.499266+00:00', '2026-08-06T19:27:26.415465+00:00', '', '', 'Salta', '', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493884133481', 'Juliocesar', 'Cierre', 'Creta', '25000000', NULL, 'Cliente Juliocesar Escalante (email julioescalante.77@gmail.com, tel +543884133481) completó formulario por anuncio de Hyundai Creta con entrega inmediata. Se envió imagen principal del Creta. Es de Jujuy, ciudad Perico; se le explicó que será atendido por llamada/mensaje desde Salta. Confirmó uso particular. Preguntó por precio y financiación; se le explicó que un asesor le da esos datos exactos. Indicó que cuenta con $25 millones en efectivo/contado (no permuta). Confirmó que quiere avanzar y ser contactado por un asesor por WhatsApp, sin restricción de horario. Mostró interés en la versión inicio de gama del Creta. Confirmó nuevamente que quiere ser contactado por WhatsApp para conocer precio y stock de esa versión.', '2026-08-06T11:45:14.275603+00:00', '2026-08-06T15:03:15.619482+00:00', 'julioescalante.77@gmail.com', 'Escalante', 'Jujuy', 'Perico', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Inicio de gama', 'Particular', 'Contado', 'Cualquier horario, por WhatsApp', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493888362923', '', 'Abierta', 'HB20', '', NULL, 'Cliente llegó por anuncio del Hyundai HB20. Es de Jujuy, se atiende por llamada desde Salta. Se le envió imagen principal del HB20. Preguntó dirección de la sucursal en Salta (Pellegrini 1030) y luego pidió el número de teléfono de contacto, que se le proporcionó. Respondió ''bien gracias'' a un saludo. Aún no brindó su nombre, se le vuelve a consultar.', '2026-08-04T09:09:45.771262+00:00', '2026-08-07T14:24:44.042333+00:00', '', '', 'Jujuy', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493876407822', 'Leo', 'Cierre', 'Tucson', '', NULL, 'Cliente Leo Jimenez, de San José de Metán, Salta, llegó por anuncio del Tucson Safety. Será atendido desde sucursal Salta por WhatsApp, sin horario fijo. Consultó precio, financiación y permuta - se le explicó que un asesor coordina esa información. Confirmó aceptando la derivación y reiteró interés en financiación. Ahora pidió que el asesor le escriba para charlar por WhatsApp; se confirmó contacto hoy mismo y se le repreguntó el detalle del vehículo a entregar en permuta.', '2026-08-07T12:47:57.184911+00:00', '2026-08-08T12:19:31.301984+00:00', '', 'Jimenez', 'Salta', 'San José de Metán', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', 'Permuta', 'Sin horario fijo, responde cuando lee los mensajes', 'false', '', 'Interesado en entregar un usado, sin detalles aún', '2026-08-08 09:19');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492613074450', 'Laura', 'Cierre', 'Creta', '', NULL, 'Cliente Laura llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta, con mención de financiación y toma de usado. Preguntó por planes de financiación disponibles, se le explicó que un asesor arma la propuesta personalizada. Consultó si el Creta es híbrido; se le aclaró que es nafta. Busca algo familiar para uso particular, confirmó que sí busca un auto familiar. Ahora preguntó precio del Creta; se le explicó que el valor exacto lo brinda un asesor según versión y financiación, y se le indicó que será contactada mañana a partir de las 9hs por estar fuera de horario de atención.', '2026-08-06T22:16:32.35314+00:00', '2026-08-07T01:43:57.799661+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493885836487', '', 'Abierta', '', '', NULL, 'Cliente inició la conversación pidiendo más información general, sin especificar modelo ni otros datos. Se le preguntó el nombre para continuar la charla.', '2026-08-19T23:29:02.442979+00:00', '2026-08-19T23:29:02.442979+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493814431387', 'David', 'Cierre', 'HB20', '', NULL, 'Cliente David (Tucumán) confirmó interés en el HB20 versión Platinum Safety AT, pago de contado. Preguntó por el precio de contado; se reiteró que el valor exacto lo brinda un asesor comercial. Solicitó también la ficha técnica, que fue enviada. Será atendido por llamada/mensaje desde Salta. Falta apellido, ciudad puntual, uso previsto y coordinar horario de contacto.', '2026-08-07T12:41:21.387233+00:00', '2026-08-07T15:48:50.833239+00:00', '', '', 'Tucumán', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', 'Platinum Safety AT', '', 'Contado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815505510', 'Oscar', 'Cierre', 'HB20S', 'USD 15000 de entrega + financiación', NULL, 'Oscar había agendado llamada para el sábado 8/8 12hs sobre el Creta (USD 15000 entrega + financiación, Santiago del Estero Capital, zona Norte, uso particular, financiado, pendiente confirmar versión Safety+). También consultó por el HB20S, se le envió imagen principal, y preguntó por espacio de baúl, pendiente versión. Esa fecha ya pasó (hoy es 18/8), por lo que se le informó y se le pidió reagendar nueva fecha/hora de contacto.', '2026-07-17T15:22:13.802365+00:00', '2026-08-18T21:30:24.348753+00:00', 'oscar.greco@gmail.com', '', 'Santiago del Estero', 'Capital', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacio-interior-1.jpg:interior,https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', '', 'Particular', 'Financiado', 'Sábado 12hs', 'false', '', '', '2026-08-08 12:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815635227', 'Gustavo', 'Cierre', 'Tucson', '', NULL, 'Gustavo (Salta) sigue interesado en Tucson Safety+ para uso familiar particular. Ya se ofreció prueba de manejo. Ahora expresó preocupación por no tener presupuesto (''no tengo un mango''), lo que sugiere objeción de financiamiento. Se le explicó que existen opciones de financiamiento y que un asesor puede armar la mejor alternativa según su situación. Se propuso coordinar contacto. Faltan definir ciudad, forma de pago, fecha de prueba de manejo y confirmar derivación con asesor.', '2026-07-17T12:18:16.999435+00:00', '2026-08-03T14:14:15.408591+00:00', '', '', 'Salta', '', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacio-interior-1.jpg:interior,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral,https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2026/07/Nuestros-Vehiculos.png:catalogo,https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-Tucson-asientos-interior.jpg:asientos', 'Safety+', 'Particular', 'Financiado', '', 'true', 'lunes 9:30hs (propuesta, pendiente confirmación)', '', NULL);
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492664030268', 'Omar', 'Cierre', 'Creta', '', NULL, 'Cliente Omar (Tilcara, Jujuy) llegó por anuncio de la Nueva Hyundai Creta preguntando precio. Se le explicó que el valor lo brinda un asesor. Confirmó que quiere que le escriban/contacten por WhatsApp, y se le informó que será atendido desde Salta por ser zona Norte. Respondió ''Nop'' y luego ''👍'' sin agregar información nueva. Se insiste en preguntar horario preferido de contacto. Falta registrar apellido, forma de pago, uso previsto y horario preferido de contacto.', '2026-08-06T16:30:50.641373+00:00', '2026-08-06T19:45:53.857848+00:00', '', '', 'Jujuy', 'Tilcara', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492901447633', 'Carlos', 'Abierta', '', '', NULL, 'Cliente saludó y consultó por un repuesto, se lo derivó al equipo de posventa/repuestos con el número de contacto oficial. Confirmó que ya se comunicó con ese equipo y agradeció. Ahora se presentó como Carlos, aclaró que por el momento no está en condiciones de mirar nada. Todavía no se registró modelo de interés, provincia ni otros datos.', '2026-08-06T12:12:12.713272+00:00', '2026-08-06T15:34:54.924437+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492346506920', 'Carmen', 'Cierre', 'Tucson', '', NULL, 'Cliente Carmen llegó por anuncio del Tucson Safety (SmartSense/ADAS). Uso particular, provincia Santiago del Estero, atendida por llamada/mensaje desde Salta salvo visitas puntuales. Aceptó test drive en Salta. Avisó que está en Salta hoy; se le propuso visitar la sucursal (Pellegrini 1030) dentro del horario de atención (hasta 17hs) para coordinar el test drive presencial. Carmen dice que avisa antes de ir, pero todavía no confirma horario exacto. Falta apellido, ciudad puntual, forma de pago y horario exacto de visita.', '2026-08-06T12:07:08.734152+00:00', '2026-08-06T15:37:46.171943+00:00', '', '', 'Santiago del Estero', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', 'Particular', '', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493854755486', 'Sara', 'Cierre', 'Creta', '', NULL, 'Sara llegó por anuncio de New Creta, confirmó interés real, pagaría al contado. Está en Santiago del Estero, atendida por llamada/mensaje desde Salta. Preguntó si cambia mucho el precio y ahora insiste en cómo conseguir el precio publicado; se reiteró que el valor final lo confirma un asesor según versión y forma de pago, y que la contactan hoy mismo. Falta capturar apellido, ciudad puntual, email y coordinar el contacto.', '2026-08-07T09:08:21.309695+00:00', '2026-08-07T12:30:04.976739+00:00', '', '', 'Santiago del Estero', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Contado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874586723', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta con entrega inmediata. Completó formulario y pide más información. Todavía no brindó nombre. Se envió imagen principal del Creta.', '2026-08-05T23:29:33.490703+00:00', '2026-08-05T23:29:33.490703+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493876419630', 'Edgardo', 'Cierre', 'Tucson', '', NULL, 'Cliente se identificó como Edgardo. Interesado en Hyundai Tucson (llegó por anuncio de Tucson Safety con SmartSense). Preguntó por precio final y financiación a tasa 0%. Se explicó que un asesor brinda esos datos y se ofreció contacto para el sábado a partir de las 9hs. Falta captar apellido, provincia/ciudad y más detalles de uso.', '2026-08-07T15:11:51.954009+00:00', '2026-08-07T23:26:55.16129+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493873000811', 'Sebastián', 'Cierre', 'Creta', '', NULL, 'Cliente Sebastián Costilla, interesado en Creta por anuncio de Facebook/Instagram con entrega inmediata y toma de usado. Uso familiar, de Salta capital. Confirmó que puede visitar la sucursal en Pellegrini para ver el Creta y hacer prueba de manejo. La cita telefónica de las 14:15 ya venció al momento de este mensaje. Sebastián confirmó que la forma de pago será financiada. Falta coordinar nuevo horario de contacto y fecha exacta de visita.', '2026-08-07T13:24:16.132559+00:00', '2026-08-07T17:19:00.564317+00:00', '', 'Costilla', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', 'Financiado', '14hs', 'true', '', '', '2026-08-07 14:15');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493884092688', 'Gustavo', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de New Creta. Muestra interés en el modelo y menciona que tiene un Corolla Cross XEI 2023 con 80.000km para entregar en parte de pago. Brindó su nombre: Gustavo. Está en Jujuy (San Salvador), será atendido por llamada o mensaje desde Salta. Confirmó horario de contacto sin preferencia específica. Preguntó por versiones del Creta; se informó Safety +. Frenó la conversación diciendo que se informa por su cuenta. La cita de contacto acordada para las 11:06 ya pasó sin confirmación de nuevo horario; cliente solo agradeció, sin dar nueva información.', '2026-08-07T11:03:02.450686+00:00', '2026-08-07T14:09:10.587365+00:00', '', '', 'Jujuy', 'San Salvador', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', 'Permuta', 'Sin preferencia horaria específica', 'false', '', 'Toyota Corolla Cross XEI 2023, 80.000 km', '2026-08-07 11:06');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491164752903', 'Gabriel', 'Cierre', 'HB20', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del Nuevo Hyundai HB20. Se envió imagen principal del modelo. Gabriel confirmó uso particular. Había coordinado contacto telefónico para el 2026-08-07 a las 13hs, pero esa fecha ya pasó. Gabriel pidió reagendar y ahora escribió ''ahora'' sin dar fecha concreta; se le propuso una llamada hoy mismo a las 17:30 dado que todavía es horario hábil (16:50). Falta definir provincia, ciudad, versión, forma de pago y presupuesto.', '2026-08-06T19:50:44.075663+00:00', '2026-08-11T19:50:14.507258+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', 'Particular', '', 'mañana 13hs', 'false', '', '', '2026-08-11 17:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491166291128', 'Jorge', 'Cierre', 'HB20', '', NULL, 'Cliente Jorge Marquez, interesado en HB20, pago de contado con dólares ahorrados. Ciudad CABA, provincia ''Otra'', fuera de zona Norte, atendido por llamada/mensaje desde Salta. Email jomarque1.1@gmail.com. Consultó precio, se derivó a asesor. Prefiere colores clásicos para el HB20. Reagendó el contacto de las 16hs a las 14hs de hoy por compromiso en su consultorio. Confirmó conformidad repetidas veces y cerró la charla con ''No gracias'', sin requerir nada más por ahora.', '2026-08-07T12:17:06.715982+00:00', '2026-08-07T15:29:18.673108+00:00', 'jomarque1.1@gmail.com', 'Marquez', 'Otra', 'Ciudad de Buenos Aires', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', 'Contado', 'antes de las 16hs', 'false', '', '', '2026-08-07 14:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874598598', 'Serio', 'Cierre', 'Tucson', '', NULL, 'Cliente (Serio) llegó por anuncio de Hyundai Tucson Safety (SmartSense, ADAS). Se envió imagen principal del Tucson. Confirmó que es de Salta, ciudad Cerrillos. Pidió información de las 3 versiones disponibles y mostró preferencia por la Híbrida 4WD HEV. Consultó precio dos veces; se le explicó que un asesor confirma el valor exacto según equipamiento y forma de pago, y se le propuso coordinar la prueba de manejo. Se le envió la ficha técnica en PDF. Falta apellido, presupuesto, uso previsto, forma de pago y coordinar fecha de prueba de manejo.', '2026-08-06T15:12:20.935757+00:00', '2026-08-06T18:34:44.213513+00:00', '', '', 'Salta', 'Cerrillos', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', 'Híbrida 4WD HEV', '', '', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493885814771', 'Gustavo', 'Cierre', 'HB20', '', NULL, 'Cliente Gustavo (Jujuy, San Salvador capital) llegó por anuncio del HB20 Comfort Plus MT con bonificación especial. Se envió imagen principal del HB20. Se le informó que será atendido por llamada/mensaje desde Salta por ser zona Norte. Confirmó que quiere avanzar, se coordinó contacto para el lunes 10/08 a las 9:30hs. En este turno confirmó ''Ok'' aceptando la coordinación. Falta uso previsto, forma de pago y demás datos.', '2026-08-09T17:55:53.653684+00:00', '2026-08-09T22:00:30.823699+00:00', '', '', 'Jujuy', 'San Salvador de Jujuy', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', 'Comfort Plus MT', '', '', '', 'false', '', '', '2026-08-10 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874062739', 'Valeria', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de New Creta con oferta de toma de usado. Preguntó cómo funciona el proceso de cambio de su vehículo usado. Se le explicó que se toma como parte de pago. Cliente se identificó como Valeria Suasnabar. Se le pregunta por el vehículo que entregaría en permuta.', '2026-08-10T11:40:20.525784+00:00', '2026-08-10T14:41:41.497216+00:00', '', 'Suasnabar', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491137671287', 'Jorge', 'Cierre', 'Creta', '', NULL, 'Cliente Jorge Lacasta (CABA, fuera de zona norte) llegó por anuncio del Creta, preguntó precio, se le explicó que lo brinda un asesor. Mostró fastidio por no recibir atención inmediata, se despidió molesto. Se intentó ofrecer contacto de un asesor pero el cliente reiteró su enojo con un ''chau'' tajante. Se cierra la conversación con tono cálido, sin insistir, dejando la puerta abierta. Pendiente: datos de versión, uso previsto, forma de pago y horario de contacto, y si el cliente decide retomar el contacto.', '2026-08-14T14:02:54.396704+00:00', '2026-08-14T17:23:13.785905+00:00', '', 'Lacasta', 'Otra', 'CABA', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815870668', 'Ernesto', 'Cierre', 'HB20', '', NULL, 'Cliente llegó por anuncio general de AGN Hyundai. Se presentó como Ernesto. Mostró interés en HB20, se le envió imagen principal. Contó que el auto sería para su hija (uso particular). Está en Tucumán Capital; se le avisó que será atendido por llamada desde Salta. Eligió versión Comfort Plus MT. Preguntó por precio, se explicó que lo brinda un asesor. Quedó coordinada llamada hoy 18hs. Ernesto bromeó varias veces pidiendo que no se insista más con el tema de la llamada ya acordada; en este turno volvió a bromear diciendo que las confirmaciones las da Geni y no él, se le siguió el humor confirmando la llamada de hoy 18hs sin insistir más. Falta presupuesto y forma de pago.', '2026-08-04T02:50:50.411327+00:00', '2026-08-04T10:26:44.51733+00:00', '', '', 'Tucumán', 'Capital', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', 'Comfort Plus MT', 'Particular', '', '18hs', 'false', '', '', '2026-08-04 18:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491140546991', 'Juan', 'Abierta', '', '', NULL, 'Cliente Juan preguntó por precios de los autos. Se le explicó que los valores exactos los confirma un asesor comercial, ya que varían según versión y forma de pago. Falta conocer modelo de interés puntual, uso previsto y provincia. Sábado fuera de horario de atención pasadas las 13hs, por lo que se mantendrá la charla hasta derivar en horario hábil.', '2026-08-01T13:39:45.845669+00:00', '2026-08-01T16:40:52.327833+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2026/07/Nuestros-Vehiculos.png:catalogo', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875239804', 'Marco', 'Cierre', 'Tucson', '', NULL, 'Marco Escribano (Salta capital) interesado en Tucson Safety, llegó por anuncio ADAS/SmartSense. Se le envió imagen principal y se ofreció test drive en sucursal Pellegrini 1030. Preguntó precio y motorización, derivado a asesor comercial por falta de ficha técnica cargada. En este turno confirmó que prefiere pasar por sucursal en persona, pero como es lunes 17:45 (fuera de horario hábil para nueva visita hoy), se le propuso coordinar para el día siguiente. Pendiente definir fecha/hora exacta de test drive, uso previsto, forma de pago y demás datos de calificación.', '2026-08-03T17:40:52.351111+00:00', '2026-08-03T20:45:51.187095+00:00', '', 'Escribano', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', 'Safety', '', '', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875845611', 'Mercedes', 'Cierre', 'Creta', '', NULL, 'Cliente Mercedes, interesada en Creta Safety+, plan de ahorro confirmado, provincia Salta ciudad Capital. Se explicó que los valores exactos los da un asesor. Eligió modalidad de contacto por llamada; se confirma que un asesor la contactará mañana desde las 9hs por estar fuera de horario de atención. Falta definir presupuesto.', '2026-08-03T21:03:26.500304+00:00', '2026-08-04T00:20:26.07591+00:00', '', '', 'Salta', 'Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', 'Plan de ahorro', '', 'false', '', '', '2026-08-04 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875707000', 'Julieta', 'Cierre', 'HB20', '', NULL, 'Cliente (Julieta, Salta capital) confirmó interés en HB20, forma de pago financiado. Consultó precio y financiación; se explicó que esos datos los brinda un asesor comercial. Descartó el test drive y pidió ser contactada por llamada mañana martes después de las 10hs. Se confirmó la llamada para el 2026-08-04 a las 10:30, cliente aceptó. Julieta agradeció y quedó a la espera del contacto. Falta definir presupuesto concreto y datos de permuta si aplica.', '2026-08-03T11:25:47.044973+00:00', '2026-08-03T15:16:48.547665+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', 'Financiado', 'después de las 10hs', 'true', '2026-08-04 09:30', '', '2026-08-04 10:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493886637930', 'Gloria', 'Abierta', '', '', NULL, 'Gloria Burgos completó un formulario de contacto, brindando su nombre completo, teléfono (+543886637930) y email (victoriagloriab@gmail.com). Todavía no expresó interés en un modelo específico ni brindó datos de ubicación o presupuesto. Se le preguntó qué modelo le interesa para continuar el descubrimiento de necesidades.', '2026-08-05T20:36:09.306717+00:00', '2026-08-05T20:36:09.306717+00:00', 'victoriagloriab@gmail.com', 'Burgos', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493863456601', '', 'Abierta', '', '', NULL, 'Cliente llegó por anuncio general de AGN sin modelo específico. Preguntó reiteradamente por lista de usados; se le reiteró que solo se manejan 0km. Cliente aún no brinda su nombre pese a habérselo pedido varias veces en distintos turnos.', '2026-08-04T09:11:00.352854+00:00', '2026-08-04T12:35:07.989399+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874083061', 'Gustavo', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio publicitario de la New Creta 0km (entrega inmediata, toma de usados, financiación). Se envió imagen principal del modelo. Cliente se identificó como Gustavo, confirmó que es de la provincia de Salta. Falta capturar apellido, ciudad, y demás datos de calificación (versión, uso previsto, forma de pago, presupuesto).', '2026-08-06T09:31:18.221038+00:00', '2026-08-06T12:32:22.195219+00:00', '', '', 'Salta', '', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815533107', '', 'Abierta', '', '', NULL, 'Cliente llegó por anuncio general de AGN Hyundai (sin modelo específico mencionado). Se le preguntó el nombre para continuar la charla.', '2026-08-06T19:44:22.79657+00:00', '2026-08-06T19:44:22.79657+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493813375925', '', 'Abierta', 'HB20', '', NULL, 'Cliente llegó por anuncio de HB20 (financiación y toma de usado). Se envió imagen principal del modelo y se preguntó su nombre.', '2026-08-06T19:50:03.648642+00:00', '2026-08-06T19:50:03.648642+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815775764', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta preguntando por el precio. Se envió imagen principal del modelo. Se le explicó que el precio lo brinda un asesor y se le pidió nombre para continuar.', '2026-08-07T14:40:34.453487+00:00', '2026-08-07T14:40:34.453487+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493812506080', 'Juan', 'Cierre', 'HB20', '', NULL, 'Juan Ortiz, interesado en HB20 financiado (tasa 0), tiene llamada confirmada para hoy martes 18/08 a las 16:30hs. Su provincia es Tucumán, ciudad Yerba Buena, será atendido por llamada desde Salta. Email confirmado: joselo03@hotmail.com. En este turno pidió que lo llamen ahora mismo; se le aclaró que la llamada ya está coordinada para las 16:30hs como estaba acordado.', '2026-07-27T15:58:35.565738+00:00', '2026-08-18T16:04:18.194661+00:00', 'joselo03@hotmail.com', 'Ortiz', 'Tucumán', 'Yerba Buena', 'Norte', '', '', '', '', 'Financiado', 'Mañana martes 16:30hs aprox.', 'false', 'martes 16:30hs (llamada)', '', '2026-08-18 16:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493834642097', 'Ricardo', 'Cierre', 'HB20S', '', NULL, 'Cliente Ricardo Nieva (Catamarca, provincia ''Otra'') confirmó interés en HB20S para uso particular, versión Platinum Safety AT. Ya se le explicó que será atendido por llamada/mensaje desde Salta. Se le envió ficha técnica PDF y mencionaron versiones disponibles (Comfort Plus MT y Platinum Safety AT). Preguntó por precio, se derivó a asesor. Contacto acordado para lunes 2026-08-10 09:00 en horario comercial. Confirmó que sí desea mantener ese contacto acordado.', '2026-08-07T21:44:44.454401+00:00', '2026-08-08T01:15:40.597566+00:00', 'Ricardoarielantonionieva@hotmail.com', 'Nieva', 'Otra', 'Catamarca', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', 'Platinum Safety AT', 'Particular', '', '', 'false', '', '', '2026-08-10 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816791788', 'Manuel', 'Cierre', 'HB20', '', NULL, 'Cliente (Manuel) confirmó interés en el HB20 para uso comercial/trabajo, en San Miguel de Tucumán. Se le explicó que precio varía según versión y forma de pago, y se derivó a asesor. Pidió contacto inmediato por WhatsApp y lo confirmó varias veces, aclarando que no busca coordinar cita sino información mientras espera el contacto. En este turno respondió ''Bueno'', sin agregar información nueva. Falta presupuesto, horario preferido y versión elegida.', '2026-08-07T19:16:52.990782+00:00', '2026-08-07T22:55:03.1642+00:00', '', '', 'Tucumán', 'San Miguel de Tucumán', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', 'Comercial', '', '', 'false', '', '', '2026-08-07 19:48');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493624263864', 'Rosana', 'Cierre', 'Creta', '', NULL, 'Cliente Rosana, de Resistencia (Chaco), llegó por anuncio de la Nueva Hyundai Creta con oferta de toma de usado y financiación. Tiene una Hyundai Creta 2021 para entregar en permuta y le interesa la nueva Creta. Al estar fuera de zona Norte, será atendida por llamada o mensaje desde la sucursal de Salta. Preguntó por la valuación de su usado; se explicó que la da el asesor. Prefiere contacto por la mañana, se confirmó llamada para el sábado 2026-08-08 a las 9:30hs. En este turno agradeció la atención y dijo que no necesita nada más por ahora; se reconfirmó la cita y se dejó la puerta abierta para cualquier duda. Falta registrar email, versión de interés y uso previsto.', '2026-08-07T18:12:42.203037+00:00', '2026-08-07T21:18:25.617274+00:00', '', '', 'Otra', 'Resistencia', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', 'Por la mañana', 'false', '', 'Hyundai Creta 2021', '2026-08-08 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493865690255', 'Maxi', 'Cierre', 'HB20', '', NULL, 'Cliente Maxi Torres, de Tucumán, interesado en HB20 Comfort Plus MT. Ya se le había derivado a asesor para precio/financiación y confirmó preferencia de contacto por WhatsApp. En este turno aclaró que no es necesario saber la ciudad para coordinar el contacto por WhatsApp. Sigue pendiente conocer ciudad puntual y horario de contacto preferido.', '2026-08-07T19:43:29.011371+00:00', '2026-08-07T22:46:36.139065+00:00', '', 'Torres', 'Tucumán', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', 'Comfort Plus MT', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493873587702', 'Cristián', 'Cierre', 'HB20S', '', NULL, 'Cliente (Cristián) consultó por la versión ''full'' del HB20S, confirmada como Platinum Safety AT. Es de Tartagal, Salta, fuera de zona con visita presencial; contacto por WhatsApp coordinado para el lunes 10/08 a las 9hs. Cristián confirmó el contacto (''Bueno'') y luego confirmó que sí, en referencia al uso diario del auto. Se le preguntó si el uso será particular o de trabajo. Falta apellido, presupuesto, uso previsto, forma de pago y horario preferido de contacto.', '2026-08-09T22:49:00.776262+00:00', '2026-08-10T02:20:27.383299+00:00', '', '', 'Salta', 'Tartagal', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', 'Platinum Safety AT', '', '', '', 'false', '', '', '2026-08-10 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493886865522', '', 'Abierta', '', '', NULL, 'Cliente llegó por anuncio general de AGN Hyundai (sin modelo específico mencionado). Se le preguntó el nombre para continuar la conversación.', '2026-08-07T21:53:05.619896+00:00', '2026-08-07T21:53:05.619896+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491163989044', '', 'Cierre', '', '', NULL, 'Cliente contactó preguntando por el precio full de un vehículo sin especificar modelo. Se le explicó que los valores exactos los brinda un asesor comercial según versión y forma de pago. Se le informó que será contactado el sábado en horario comercial (desde las 9hs) dado que escribió de madrugada. Aún no se registró nombre, modelo de interés, ni provincia.', '2026-08-08T00:06:13.384613+00:00', '2026-08-08T00:06:13.384613+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493885977334', 'Mario', 'Cierre', 'Creta', '', NULL, 'Cliente Mario Hurtado (La Quiaca, Jujuy, zona Norte) mantiene interés en el New Creta, con cita telefónica coordinada para el sábado 2026-08-08 a las 9:30hs. Vive solo, uso particular, viaja en ruta dos veces por semana y confirmó que solo lleva equipaje de mano, lo cual refuerza que el Creta se ajusta bien a sus necesidades. Mario confirmó que espera la llamada agendada. Aún sin versión, forma de pago ni email registrados. Será atendido desde Salta por tratarse de zona Norte.', '2026-08-07T21:49:33.056915+00:00', '2026-08-08T01:04:59.453487+00:00', '', 'Hurtado', 'Jujuy', 'La Quiaca', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', '', '', 'false', '', '', '2026-08-08 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493872209925', 'Carolina', 'Cierre', 'Creta', '', NULL, 'Cliente (Carolina, Salta capital) llegó por anuncio del Nueva Creta 0km. Se le indicó dirección de sucursal (Pellegrini 1030) y se ofreció prueba de manejo. Preguntó por motor y precio del Creta Safety Plus; se explicó que esos datos los confirma un asesor. Había dudado de poder ir presencialmente y se le ofreció alternativa telefónica. Ahora aclaró que irá en unos días, sin fecha puntual todavía. Se le propuso coordinar un horario aproximado. Falta capturar apellido, uso previsto, forma de pago y confirmar horario exacto de contacto.', '2026-08-09T16:41:57.232216+00:00', '2026-08-09T20:00:40.447501+00:00', '', '', 'Salta', 'Salta capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety Plus', '', '', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815523221', 'Matías', 'Cierre', 'Creta', '', NULL, 'Cliente de Tucumán (Matías Romano) consulta por Hyundai Creta Safety, preguntó precio y disponibilidad. Se le explicó que será atendido desde Salta por llamada/mensaje. Ya brindó su nombre completo. Se envió imagen principal del Creta. Prefiere ser contactado por mensaje en horario de siesta. Confirmó que su ciudad es San Miguel de Tucumán. Cliente aceptó y agradeció, quedando confirmada la derivación a un asesor para contactarlo por mensaje en horario de siesta. Cliente cerró la conversación agradeciendo, sin nuevas solicitudes.', '2026-08-10T08:42:44.39049+00:00', '2026-08-10T11:54:31.175651+00:00', '', 'Romano', 'Tucumán', 'San Miguel de Tucumán', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety', '', '', 'Por la siesta, prefiere mensaje', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493876663888', '', 'Abierta', 'Tucson', '', NULL, 'Cliente llegó por anuncio de Hyundai Tucson Safety (seguridad SmartSense, ADAS, entrega inmediata). Se envió imagen principal de Tucson. Cliente pidió más información genérica; se le repreguntó el nombre, aún sin registrar.', '2026-08-10T12:05:58.513444+00:00', '2026-08-10T15:06:43.078573+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875923892', 'Maria Josefa', 'Abierta', 'Tucson', '', NULL, 'Cliente llegó por anuncio de Hyundai Tucson Safety (seguridad SmartSense, entrega inmediata, financiación). Se envió imagen principal de Tucson. Cliente preguntó de forma poco clara (''Es la que tiene''), se confirmó que la Tucson cuenta con SmartSense. Cliente se identificó como Maria Josefa Garcia. Falta registrar provincia, ciudad y demás datos de contacto.', '2026-08-08T12:59:21.027011+00:00', '2026-08-08T22:18:14.863679+00:00', '', 'Garcia', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492954664896', 'Verónica', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta con oferta de financiación y toma de usado. Se identificó como Verónica, de Telén, La Pampa (fuera de zona Norte). Confirmó que acepta ser atendida por mensaje/WhatsApp desde Salta. Pidió coordinar contacto con asesor para financiación y toma de usado; se le confirmó que la contactarán por WhatsApp. Preguntó por el Santa Fe como modelo nuevo, se le explicó que no hay info cargada aún. Confirmó y reconfirmó datos de permuta: Hyundai Santa Fe 2016, 80.000km. En este turno no hizo pregunta nueva, se reforzó la confirmación de derivación y se le pidió el email. Sigue pendiente definir versión del Creta, uso previsto y forma de pago final del saldo.', '2026-08-08T00:13:24.783402+00:00', '2026-08-08T03:59:40.958341+00:00', '', '', 'La Pampa', 'Telén', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', 'Hyundai Santa Fe 2016, 80.000km', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493814431096', '', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta preguntando precio. Se envió imagen principal del modelo. Se explicó que el valor exacto lo brinda un asesor (fuera de horario de atención, sábado antes de las 9). Falta capturar nombre, provincia y ciudad.', '2026-08-08T08:13:06.746327+00:00', '2026-08-08T08:13:06.746327+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493837693208', 'Juan', 'Cierre', 'Creta', '', NULL, 'Cliente Juan Bordon, de Tinogasta, Catamarca (provincia ''Otra'', fuera de zona Norte), interesado en Hyundai Creta para uso particular/familiar. Tiene Chevrolet Tracker 4x4 LTZ full 2015 en buen estado para permuta. Confirmó estar de acuerdo en ser atendido por WhatsApp desde Salta. Coordinó contacto para hoy sábado 08/08 a las 9:55. Cliente confirmó conforme y a la espera del contacto pautado, reiterando su conformidad.', '2026-08-08T08:47:27.963509+00:00', '2026-08-08T11:58:15.336123+00:00', '', 'Bordon', 'Otra', 'Tinogasta', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', 'Permuta', 'en 1 hora (09:55 aprox)', 'false', '', 'Chevrolet Tracker 4x4 integral LTZ full 2015, buen estado', '2026-08-08 09:55');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874412577', 'Juan', 'Abierta', 'Tucson', '', NULL, 'Cliente llamado Juan contactó por anuncio de Hyundai Tucson Safety (paquete SmartSense/ADAS). Se envió imagen principal de Tucson. Falta relevar provincia, ciudad, uso previsto y demás datos.', '2026-08-08T09:24:57.758281+00:00', '2026-08-08T09:24:57.758281+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493883506778', '', 'Abierta', 'Tucson', '', NULL, 'Cliente llegó por anuncio de Hyundai Tucson Safety, destacando el paquete SmartSense de seguridad activa. Se envió imagen principal del modelo. Falta capturar nombre y demás datos.', '2026-08-08T09:47:44.609282+00:00', '2026-08-08T09:47:44.609282+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492657203148', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta preguntando precio. Se envió imagen principal del modelo. Se explicó que el precio exacto lo brinda un asesor según versión y forma de pago. Se le preguntó el nombre, aún sin registrar.', '2026-08-08T10:37:28.224198+00:00', '2026-08-08T10:37:28.224198+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493834345996', 'Ariel', 'Cierre', 'Creta', '', NULL, 'Cliente Ariel (Catamarca, fuera de zona Norte) llegó por anuncio del Creta, interesado en financiación. Se le avisó que será atendido por llamada o mensaje desde Salta. Preguntó por costos; se explicó que el valor exacto lo brinda un asesor según versión y forma de pago (Financiado). Agradeció la info. Falta precisar la ciudad exacta para coordinar el contacto y validar si acepta la modalidad remota.', '2026-08-08T11:57:43.024955+00:00', '2026-08-08T15:03:23.264237+00:00', '', '', 'Catamarca', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacio-interior-1.jpg:interior', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815117224', 'Marcos', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta. Se identificó como Marcos Made, de Banda del Río Salí, Tucumán, por lo que será atendido por llamada/WhatsApp desde Salta. Consultó precio y financiación; se explicó que esos datos los brinda un asesor. En este turno pidió que le escriban por WhatsApp; se confirmó contacto para el lunes a primera hora dado que es domingo. Falta definir versión, uso previsto, forma de pago y email.', '2026-08-09T10:56:14.067286+00:00', '2026-08-09T14:16:10.649821+00:00', '', 'Made', 'Tucumán', 'Banda del Río Salí', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', 'Prefiere contacto por mensaje/WhatsApp', 'false', '', '', '2026-08-10 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874180680', 'Humberto', 'Cierre', 'Creta', '', NULL, 'Cliente (Humberto Guantay) consultó por el precio de la New Creta un domingo fuera de horario de atención. Se le explicó que el valor exacto lo brinda un asesor y que será contactado el lunes en horario comercial. El cliente confirmó su nombre (Humberto Guantay). Falta registrar provincia/ciudad para definir modalidad de atención.', '2026-08-09T12:59:39.554447+00:00', '2026-08-09T16:00:34.637144+00:00', '', 'Guantay', '', '', '', '', '', '', '', '', '', 'false', '', '', '2026-08-10 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816426682', 'Facundo', 'Cierre', 'HB20', '', NULL, 'Cliente Facundo Gambande confirmó permuta de su Citroën C4 Lounge THP 165cv 2017 (104.000 km). Interesado en Hyundai HB20 (imagen principal ya enviada). Ciudad Tucumán capital, atendido por llamada/mensaje desde Salta. Aceptó la derivación para cotizar el HB20 considerando la permuta; como es domingo, se le informó que un asesor lo contactará el lunes en horario comercial. Falta definir versión y uso previsto.', '2026-08-09T15:13:37.618159+00:00', '2026-08-09T18:18:19.859875+00:00', '', 'Gambande', 'Tucumán', 'Tucumán capital', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', 'Permuta', '', 'false', '', 'Citroën C4 Lounge THP 165cv, modelo 2017, 104000 km', '2026-08-10 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492995818267', '', 'Cierre', 'Tucson', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Tucson, mostrando interés en cotizar y posiblemente entregar un usado. Se envió imagen principal del modelo. Cliente pidió que lo llamen después de las 14hs del día siguiente (lunes 10/08); se confirmó el horario de contacto acordado. Cliente respondió ''Ok Claudio'', posiblemente confundiendo el nombre del asesor. Todavía falta capturar su nombre y apellido para completar la derivación.', '2026-08-09T17:37:16.403588+00:00', '2026-08-09T21:01:01.776794+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', '', '', 'después de las 14hs', 'false', '', '', '2026-08-10 14:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493834967066', '', 'Abierta', '', '', NULL, 'El cliente inició la conversación saludando. Todavía no se registró nombre ni modelo de interés.', '2026-08-11T21:33:57.148692+00:00', '2026-08-11T21:33:57.148692+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492235964378', 'Damián', 'Cierre', 'Creta', '', NULL, 'Cliente Damián (Buenos Aires, Mar del Plata) llegó por anuncio del New Creta con oferta de financiación 24 cuotas tasa cero. Se explicó que un asesor da el detalle exacto. Se envió imagen principal del Creta. Confirmó que acepta ser atendido desde Salta al ser zona fuera de cobertura, y confirmó explícitamente que prefiere contacto solo por mensaje. Se le pidió el email para avanzar. Pendiente capturar apellido, email y horario exacto de contacto.', '2026-08-10T13:10:42.022807+00:00', '2026-08-10T16:14:48.051151+00:00', '', '', 'Buenos Aires', 'Mar del Plata', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815164004', 'Walter', 'Cierre', 'HB20S', '', NULL, 'Walter llegó por un anuncio, mostró interés en el HB20S (se envió imagen principal). Uso previsto particular, de San Miguel de Tucumán, atendido por mensaje/llamada desde Salta. Se había coordinado contacto para las 10:47 del 12/08 pero Walter reportó que nunca lo contactaron. Se reagenda contacto inmediato para las 12:30 del mismo día. Faltan datos de presupuesto, forma de pago, versión y email.', '2026-08-12T10:43:34.588474+00:00', '2026-08-12T15:20:15.270881+00:00', '', '', 'Tucumán', 'San Miguel de Tucumán', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', '', 'Particular', '', 'ahora', 'false', '', '', '2026-08-12 12:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816449825', 'César', 'Cierre', 'HB20S', '', NULL, 'Cliente (César) interesado en HB20S versión Platinum Safety AT, en etapa Cierre. Ya recibió ficha técnica en PDF. Ciudad San Miguel de Tucumán (zona Norte, fuera de Salta). Preguntó por precio; se le explicó que lo brinda un asesor según forma de pago. Eligió contacto por WhatsApp desde Salta. Uso previsto: particular, para viajes. Citas de 15:57 y 16:21 vencieron sin confirmarse. César mostró fastidio por repetición de preguntas y por falta de respuesta directa; se le pidió disculpas y se retomó consulta de forma de pago para agilizar derivación. Falta definir apellido, presupuesto y forma de pago.', '2026-08-10T00:16:27.64439+00:00', '2026-08-10T19:24:14.010222+00:00', '', '', 'Tucumán', 'San Miguel de Tucumán', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2026/07/Nuestros-Vehiculos.png:catalogo, https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', 'Platinum Safety AT', 'Particular', '', 'Ahora mismo', 'false', '', '', '2026-08-10 16:24');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815739950', '', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de New Creta con financiación y toma de usado. Insistió preguntando por planes de financiación disponibles. Se reitera que un asesor brinda detalles según perfil, se solicita nombre para poder derivar el contacto. Falta capturar nombre, provincia y datos de contacto.', '2026-08-14T09:40:14.082554+00:00', '2026-08-14T12:56:11.994406+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491158264403', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta y preguntó por el precio. Se le explicó que el valor exacto lo brinda un asesor. Se envió imagen principal del Creta. Falta capturar nombre y datos de contacto.', '2026-08-14T11:13:15.204793+00:00', '2026-08-14T11:13:15.204793+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875653225', 'Luis', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de Nueva Hyundai Creta preguntando por planes de financiación. Se le envió imagen principal del Creta y se explicó que un asesor brinda detalles de financiación personalizados. Cliente se identificó como Luis, forma de pago financiado, provincia Salta, ciudad Salta Capital. Falta capturar apellido y otros datos. Se le propone coordinar visita a sucursal para test drive.', '2026-08-13T20:59:14.717224+00:00', '2026-08-14T00:05:05.455963+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815149930', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Nueva Hyundai Creta preguntando precio. Se le envió imagen principal del modelo y se explicó que el precio lo brinda un asesor según versión y forma de pago. Falta capturar nombre y datos de contacto.', '2026-08-13T22:25:46.37838+00:00', '2026-08-13T22:25:46.37838+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491130613706', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Nueva Creta (cotización de usado). Preguntó precio de la Creta. Se le explicó que el valor lo brinda un asesor y se coordinará contacto mañana desde las 9hs. Falta capturar nombre, provincia y ciudad.', '2026-08-13T23:30:19.07161+00:00', '2026-08-13T23:30:19.07161+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '2026-08-14 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493834649116', 'Hugo Mario', 'Cierre', 'Creta', '', NULL, 'Cliente Hugo Mario Gonzalez, de Catamarca (fuera de zona Norte), llegó por anuncio de New Creta preguntando precio. Se le explicó que el valor lo define un asesor según versión y forma de pago, y que la modalidad de contacto será por llamada o mensaje desde Salta. Mencionó que quiere entregar su vehículo actual en permuta, pendiente de detalle. Confirmó que prefiere ser contactado mañana porque hoy se duerme, quedando pendiente coordinar franja horaria exacta para la llamada.', '2026-08-14T00:16:46.213152+00:00', '2026-08-14T03:19:45.705944+00:00', '', 'Gonzalez', 'Catamarca', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491140657083', '', 'Abierta', '', '', NULL, 'Cliente llegó por anuncio genérico de AGN Hyundai en Estados. Todavía no especificó modelo de interés. Se le preguntó el nombre para continuar la charla.', '2026-08-13T23:32:56.505062+00:00', '2026-08-13T23:32:56.505062+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493415626864', 'Sergio', 'Cierre', 'Creta', '', NULL, 'Cliente Sergio (Rosario, Santa Fe, fuera de zona) llegó por anuncio del Creta con toma de usado. Entrega en permuta un Nissan Kicks Sense 2023, GNC, 95.000 km. Se le explicó que será atendido por llamada o mensaje desde Salta. Confirmó ser contactado por mensaje el 15/08 al mediodía. En este turno pidió y se le envió la ficha técnica PDF del Creta y una foto adicional del exterior.', '2026-08-14T00:27:37.586156+00:00', '2026-08-14T03:33:54.624808+00:00', '', '', 'Otra', 'Rosario', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral', '', '', 'Permuta', 'mediodía', 'false', '', 'Nissan Kicks Sense 2023, GNC, 95.000 km', '2026-08-15 12:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493329560596', 'Marcos', 'Cierre', 'Creta', '', NULL, 'Cliente (Marcos) llegó por anuncio de Facebook/Instagram del Creta preguntando precio. Se explicó que el valor exacto lo da un asesor según versión y forma de pago. Marcos es de San Pedro, Buenos Aires (fuera de zona Norte); aceptó ser atendido desde Salta y eligió que el contacto sea por mensaje/WhatsApp. Falta confirmar horario preferido, uso previsto, forma de pago y versión.', '2026-08-14T13:03:41.311009+00:00', '2026-08-14T16:07:37.904281+00:00', '', '', 'Buenos Aires', 'San Pedro', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491161252813', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la Nueva Hyundai Creta. Se le envió imagen principal del modelo. Pidió el video (no disponible, se ofreció alternativa). En este turno preguntó por los colores disponibles del Creta; se le respondió y se volvió a pedir el nombre, que aún no se registró.', '2026-08-15T15:39:48.355687+00:00', '2026-08-15T18:43:17.204845+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492975203331', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook de la Nueva Creta, mencionando financiación y toma de usado. Preguntó por planes de financiación disponibles. Se envió imagen principal de Creta. Aún no se registró nombre, provincia ni otros datos.', '2026-08-15T16:14:41.463067+00:00', '2026-08-15T16:14:41.463067+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493704279963', 'Santiago', 'Cierre', 'Creta', '', NULL, 'Cliente Santiago Leguizamón llegó por anuncio del New Creta 0km. Se le envió imagen principal del Creta. Compartió teléfono y email. Provincia: Formosa (fuera de zona Norte), será atendido por llamada/mensaje desde Salta. Confirmó ciudad Formosa Capital y uso previsto diario para trabajo y familia (Particular). Forma de pago Financiado. Preguntó por financiación, se le explicó que el asesor arma la propuesta. Coordinó llamada para las 9hs del 2026-08-15. Cliente confirmó conforme con el horario acordado. Falta definir presupuesto.', '2026-08-14T17:11:27.917937+00:00', '2026-08-14T20:30:55.482812+00:00', 'santylegui@gmail.com', 'Leguizamón', 'Otra', 'Formosa Capital', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', 'Financiado', 'Mañana entre 8 y 12hs', 'false', '', '', '2026-08-15 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492945904124', 'Diego', 'Abierta', '', '', NULL, 'Cliente se presentó como Diego. Consultó por cotización de un repuesto (cazoleta de amortiguador delantero, parte 546102W000) para una Hyundai Santa Fe 2014, VIN KMHSU81CDEU270514. Se derivó al equipo de posventa/repuestos con el número de contacto, ya que no es información que se maneje en esta charla. Aún no se conoce interés en modelos 0km ni otros datos de contacto.', '2026-08-14T18:01:51.465197+00:00', '2026-08-14T21:02:29.579181+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493856096743', 'Jose', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta con oferta de financiación y toma de usado. Pidió cotización en pesos con 50% de entrega y financiación hasta 24 cuotas. Se le explicó que los valores exactos los da un asesor. Cliente se identificó como Jose Luis. Falta capturar provincia, ciudad y otros datos.', '2026-08-14T19:29:22.179995+00:00', '2026-08-14T22:30:14.324486+00:00', '', 'Luis', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815903541', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta preguntando por precio. Se envió imagen principal del modelo. Se explicó que el precio lo brinda un asesor según versión y forma de pago. Falta capturar nombre, provincia y otros datos.', '2026-08-15T11:50:32.683855+00:00', '2026-08-15T11:50:32.683855+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493413353083', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Nueva Hyundai Creta. Preguntó precio; se explicó que un asesor brinda el valor exacto según versión y forma de pago, derivación programada para el lunes en horario comercial (contacto llegó sábado fuera de horario). Se envió imagen principal del Creta. Falta capturar nombre, provincia y otros datos.', '2026-08-15T14:03:15.563082+00:00', '2026-08-15T14:03:15.563082+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816780527', 'Sebastián', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Creta. Preguntó el precio; se le explicó que un asesor lo contacta el lunes (fuera de horario de atención). Se envió imagen principal del Creta. Cliente se identificó como Sebastián y confirmó que es de Tucumán, por lo que será atendido por llamada o mensaje desde Salta. Cliente confirmó con ''Ok'' la derivación. Falta capturar apellido, ciudad y otros datos.', '2026-08-15T19:56:15.438368+00:00', '2026-08-15T22:58:16.366781+00:00', '', '', 'Tucumán', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493426125073', 'Diego', 'Desarrollada', 'Creta', '', NULL, 'Cliente (Diego) mostró interés en el New Creta y consultó por planes de financiación disponibles (Financiado). Se envió imagen principal del modelo. Diego indicó que su ciudad es Santa Fe Capital, fuera de zona de cobertura directa (Salta, Tucumán, Santiago del Estero, Jujuy). Se le explicó que sería atendido por llamada/mensaje desde Salta y se le consultó si está de acuerdo con esta modalidad. Falta confirmar aceptación, capturar email y avanzar hacia agendamiento.', '2026-08-15T16:28:22.037256+00:00', '2026-08-15T19:48:08.267714+00:00', '', '', 'Otra', 'Santa Fe Capital', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493844671387', 'Pedro', 'Cierre', 'Creta', '', NULL, 'Cliente Pedro Eleias llegó por anuncio de la Nueva Hyundai Creta. Preguntó por precio, se le explicó que lo brinda un asesor y que sería contactado el lunes 17/08 a las 9hs en horario comercial. Se envió imagen principal del Creta. Es de la provincia de Santiago del Estero, ciudad Santiago (capital), por lo que será atendido por llamada/mensaje desde Salta. Falta email, versión, uso previsto y forma de pago.', '2026-08-15T20:16:06.045126+00:00', '2026-08-15T23:42:40.0135+00:00', '', 'Eleias', 'Santiago del Estero', 'Santiago', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '2026-08-17 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492994718889', 'María', 'Desarrollada', 'Tucson', '', NULL, 'Cliente (María) llegó por anuncio de la Nueva Tucson con cotización de usado. Se le envió imagen principal y confirmó su nombre. Indicó uso familiar y para todo el día. Informó que está en Neuquén, provincia fuera de zona Norte, se le explicó que sería atendida por un asesor desde Salta, y confirmó que le sirve esa modalidad. Falta ciudad, presupuesto y forma de pago.', '2026-08-16T09:34:41.300578+00:00', '2026-08-16T13:00:02.848271+00:00', '', '', 'Otra', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/Hyundai-tucson-destacados-botton-cta-disenio.jpg:principal', '', 'Particular', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493885074562', 'Martin', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio publicitario del New Creta 0km con entrega inmediata y toma de usado. Se envió imagen principal del Creta. Cliente se identificó como Martín. Preguntó específicamente por la ciudad (parece estar respondiendo a una pregunta sobre provincia previa). Falta capturar apellido, provincia, ciudad y uso previsto.', '2026-08-15T21:44:55.484169+00:00', '2026-08-16T00:53:02.729724+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491141863811', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la New Creta 0km con entrega inmediata y toma de usados. Se le envió la imagen principal del Creta. Falta capturar nombre y demás datos.', '2026-08-17T19:55:03.102641+00:00', '2026-08-17T19:55:03.102641+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491156298352', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta. Preguntó por el precio del modelo y se le explicó que el valor exacto lo brinda un asesor según versión y forma de pago. Se le envió imagen principal del Creta. Luego preguntó si el Creta es eléctrico o solo motorizado a combustión; se le aclaró que es únicamente motorizado. Falta capturar nombre, provincia y otros datos de calificación.', '2026-08-16T11:36:17.890748+00:00', '2026-08-16T14:37:32.895629+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816436789', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta preguntando por el precio. Se envió imagen principal del modelo. Se explicó que el precio exacto lo brinda un asesor y se coordinará contacto el lunes en horario comercial, ya que es domingo. Falta capturar nombre, provincia y otros datos del cliente.', '2026-08-16T13:17:27.86371+00:00', '2026-08-16T13:17:27.86371+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
