INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492996904030', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la Nueva Hyundai Creta con oferta de toma de usado y financiación. Preguntó cómo funciona el proceso de cambio de su vehículo usado. Se le envió imagen principal de Creta y se le explicó que un asesor tasa el usado. Falta capturar nombre.', '2026-08-16T16:09:53.986443+00:00', '2026-08-16T16:09:53.986443+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492396427411', 'Luciano', 'Abierta', '', '', NULL, 'Luciano Cozzarin (tel 2396427411) contactó por primera vez pidiendo información general, sin mencionar modelo específico todavía.', '2026-08-16T19:52:58.054763+00:00', '2026-08-16T19:52:58.054763+00:00', '', 'Cozzarin', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493886401124', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio publicitario del New Creta 0km con entrega inmediata. Se envió imagen principal del modelo. Preguntó por precio y financiación; se explicó que valores exactos los da un asesor y se coordinará contacto el lunes en horario comercial por ser domingo. Cliente confirmó estar de acuerdo con la derivación. Falta capturar nombre y datos de contacto.', '2026-08-16T20:15:41.706141+00:00', '2026-08-16T23:16:55.370008+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
