INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493834941454', 'Mario', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la New Creta 0km con entrega inmediata. Se envió imagen principal del Creta. Cliente se identificó como Mario Nieva, de Catamarca (fuera de zona Norte). Confirmó que acepta ser atendido por llamada/mensaje desde Salta. Forma de pago: combinación de contado y financiado. Confirmó vehículo en permuta: Citroën C4 Cactus 2020, VTI Feel 1.6, kilometraje aproximado 140.000 km. Versión de interés: Safety +. Cliente confirmó que puede ser contactado a cualquier hora hoy, se registró como horario de contacto. Falta presupuesto exacto y uso previsto.', '2026-08-17T00:41:56.27905+00:00', '2026-08-17T13:25:41.558586+00:00', '', 'Nieva', 'Otra', 'Catamarca', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', 'Financiado', 'Cualquier hora, hoy', 'false', '', 'Citroën C4 Cactus, año 2020, VTI Feel 1.6, aproximadamente 140.000 km', '2026-08-17 10:25');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491152470345', 'Antonio', 'Abierta', 'Creta', '27.500 USD', NULL, 'Cliente se identificó como Antonio Sánchez. Llegó por anuncio de Nueva Creta, mencionó precio de referencia (27.500 USD) y pidió catálogo/fotos. Se enviaron dos imágenes (principal y exterior lateral). En este turno pidió nuevamente una imagen, se le aclaró que ya se le había enviado. Falta capturar provincia, ciudad y demás datos.', '2026-08-16T21:24:40.465891+00:00', '2026-08-17T00:28:10.450055+00:00', '', 'Sanchez', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal,https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491133293079', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre el New Creta, mencionando cotización de usado y financiación. Preguntó por planes de financiación disponibles. Se envió imagen principal del Creta y se explicó que un asesor arma la propuesta de financiación según su perfil. Se le pidió nombre para continuar la charla.', '2026-08-17T00:14:13.016857+00:00', '2026-08-17T00:14:13.016857+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Financiado', '', 'false', '', '', '');
