INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816814896', 'Héctor', 'Cierre', 'Creta', '', NULL, 'Cliente (Héctor) llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta preguntando por el precio. Se le explicó que el valor exacto lo brinda un asesor según versión y forma de pago. Se envió imagen principal del Creta. Cliente pidió agendar y propuso coordinar por mensaje mañana martes a las 9:30, se confirmó. Héctor indicó que es de Tucumán, por lo que será atendido por mensaje/llamada desde Salta. Falta capturar apellido, ciudad y forma de pago.', '2026-08-17T08:29:36.449764+00:00', '2026-08-17T11:49:48.039842+00:00', '', '', 'Tucumán', '', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '2026-08-18 09:30');
