INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815278437', 'Carlos', 'Cierre', 'HB20', '', NULL, 'El cliente se llama Carlos, está en Tucumán (Capital), busca un auto chico de 5 puertas para uso diario y particular, interesado en el HB20. Confirmó uso personal y forma de pago financiado. Pidió que lo llamen desde Salta y acordó horario de contacto a las 15hs del 18/08. Confirmó conformidad con la cita agendada. Falta definir presupuesto.', '2026-08-18T13:05:58.173094+00:00', '2026-08-18T16:16:49.516414+00:00', '', '', 'Tucumán', 'Capital', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', 'Particular', 'Financiado', '15hs', 'false', '', '', '2026-08-18 15:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875058651', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del Nuevo Creta. Preguntó horarios de atención, se le informó (L-V 9-18hs, Sáb 9-13hs) y se envió imagen principal del Creta. Volvió a preguntar si hoy atienden, se le confirmó que sí. Aún no se registró nombre, provincia ni otros datos.', '2026-08-17T10:33:57.321944+00:00', '2026-08-17T13:34:52.235228+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
