INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491161119392', 'Guillermo', 'Cierre', 'Creta', '', NULL, 'Cliente Guillermo Rubino (Buenos Aires, provincia ''Otra'', fuera de zona Norte) llegó por anuncio del Creta preguntando precio. Se le explicó que el valor lo da un asesor. Aceptó ser contactado por mensaje desde Salta. Preguntó por versiones disponibles, se le indicó Safety +. Preguntó por la sucursal (Pellegrini 1030, Salta), se aclaró que será contactado por mensaje al estar fuera de zona. Informó que tiene un Genesis 2.0 2010 con 97000 km para entregar en parte de pago, aclaró que es 0km (a confirmar por el asesor). Forma de pago: Permuta. Quedó agendado contacto para martes 18/08 después de las 10hs. Cliente confirmó con ''Ok'', sin nueva información.', '2026-08-17T10:49:56.226081+00:00', '2026-08-17T13:56:22.813868+00:00', '', 'Rubino', 'Otra', 'Buenos Aires', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', 'Permuta', 'mañana después de las 10hs', 'false', '', 'Genesis 2.0 2010, 97000 km (cliente aclara que es 0km, a confirmar con asesor)', '2026-08-18 10:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493876837329', 'Pablo', 'Cierre', 'HB20', '', NULL, 'Cliente Pablo llegó por anuncio general de AGN sin modelo específico. Compartió su nombre: Pablo. Mostró interés concreto en el HB20, preguntando por precio y financiación. Se le explicó que un asesor le dará los valores exactos. Confirmó que está en Salta Capital. Pidió ser contactado por WhatsApp/mensaje en lugar de visita o llamada; se confirmó que el asesor lo contactará por ese medio. Cliente agradeció y se cierra la charla cordialmente.', '2026-08-18T12:20:35.340016+00:00', '2026-08-19T12:28:56.174911+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874627469', 'Natalia', 'Cierre', 'Creta', '', NULL, 'Natalia fue a la sucursal Pellegrini 1030 para su prueba de manejo del Creta agendada hoy 17/08 15hs, pero el local estaba cerrado. Se le pidieron disculpas y se escaló como urgente. Se le propone reagendar para mañana martes 18/08 a las 9:30hs. Pendiente confirmación de Natalia.', '2026-08-17T11:01:14.397369+00:00', '2026-08-17T18:24:52.480095+00:00', '', '', 'Salta', 'Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal, https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', '', 'mañana', 'true', '2026-08-18 09:30', '', '2026-08-18 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493534195413', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta con oferta de toma de usado. Preguntó cómo funciona el proceso de cambio de su vehículo usado (permuta). Todavía no se registró nombre ni datos de contacto. Se envió imagen principal del Creta y se le pidió el nombre.', '2026-08-17T11:32:38.776162+00:00', '2026-08-17T11:32:38.776162+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492615544834', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta y preguntó el precio. Se le explicó que el valor exacto lo brinda un asesor (varía según versión y forma de pago), y que será contactado mañana a primera hora por estar fuera de horario de atención. Se le envió imagen principal del Creta. Falta capturar nombre, provincia y otros datos.', '2026-08-17T18:10:23.167858+00:00', '2026-08-17T18:10:23.167858+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875625170', 'Maximiliano', 'Abierta', '', '', NULL, 'Cliente llegó por un anuncio general de AGN sin modelo específico. Se le preguntó el nombre y respondió: Maximiliano. Aún no menciona modelo de interés, presupuesto, ni ubicación. Se le consultó sobre el uso que le daría al vehículo para orientar la conversación.', '2026-08-18T13:31:39.54371+00:00', '2026-08-18T16:32:22.74303+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493816093810', 'Leandro', 'Cierre', 'Creta', '', NULL, 'Cliente se llama Leandro, reside en San Lorenzo, Salta. Preguntó por una SUV; se le mostró el New Creta como opción principal. Confirmó uso familiar/particular. Faltan datos de presupuesto y forma de pago. Pidió que lo llamen en 20 minutos (14:50), se coordinó llamada telefónica para esa hora.', '2026-08-18T14:18:30.836441+00:00', '2026-08-18T17:29:43.076273+00:00', '', '', 'Salta', 'San Lorenzo', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', '', '', 'false', '', '', '2026-08-18 14:50');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492914668968', 'Hugo', 'Cierre', 'Creta', '', NULL, 'Cliente Hugo, de Corrientes (fuera de zona Norte, atendido desde Salta), interesado en la Nueva Creta tras ver un anuncio. Preguntó precio y financiación; se le explicó que un asesor brinda esos datos exactos. El contacto agendado para 2026-08-19 9:30 no se concretó. Hugo lo señaló y Geni propuso reagendar para el 2026-08-20 a las 9:30, pendiente de confirmación del cliente. Faltan apellido, forma de pago y email.', '2026-08-18T12:11:05.50082+00:00', '2026-08-19T20:08:10.279911+00:00', '', '', 'Otra', 'Corrientes', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', 'Mañana (día siguiente), horario a confirmar', 'false', '', '', '2026-08-20 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493464693527', 'Juan', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la Nueva Hyundai Creta y preguntó por el precio. Se envió imagen principal del modelo. Juan, de Rosario (fuera de zona), uso particular/diario. Se le explicó que la atención sería remota. Ahora Juan preguntó el valor pagando de contado; se le indicó que el asesor confirma el precio exacto según versión, y se reconfirmó modalidad remota (llamada o mensaje) para continuar el proceso.', '2026-08-18T14:44:23.300844+00:00', '2026-08-18T17:47:17.926809+00:00', '', '', 'Otra', 'Rosario', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', 'Particular', 'Contado', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875273500', 'Tomas', 'Cierre', 'HB20', '', NULL, 'Cliente (Tomás) llegó por anuncio general de AGN Hyundai. Mostró interés en el HB20, se le envió imagen principal. Confirmó que está en Salta y preguntó por financiación. Eligió ser contactado por llamada en horario de mañana. Se propuso miércoles 9:30hs, pero pidió cambiarlo a las 10hs, lo cual se confirmó. Falta apellido, ciudad, forma de pago exacta y demás datos de calificación.', '2026-08-18T17:23:02.782886+00:00', '2026-08-18T20:27:30.130798+00:00', '', '', 'Salta', '', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', '', '', 'mañana', 'false', '', '', '2026-08-19 10:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493885876796', 'Martín', 'Cierre', 'Creta', '', NULL, 'Cliente Martín Perea (San Salvador de Jujuy capital), interesado en New Creta Safety+, llegó por anuncio. Será atendido por llamada/mensaje desde Salta. Uso previsto Particular. Tiene Hyundai Creta 2018 (segundo dueño, 76.000km, cochera, gomas nuevas, auxilio sin rodar) para permuta. Consultó por adaptación para discapacidad (derivado a especialista) y diferencia de precio contado (derivado a asesor). Confirmó horario flexible por trabajar de forma particular. Cita de contacto agendada para 2026-08-19 09:30, confirmada nuevamente por el cliente. En este turno agradeció y cerró la charla cordialmente. Falta definir presupuesto y forma de pago.', '2026-08-17T14:03:17.239139+00:00', '2026-08-18T20:18:41.717495+00:00', '', 'Perea', 'Jujuy', 'San Salvador de Jujuy', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', 'Particular', '', 'Flexible, cualquier horario (trabaja particular)', 'false', '', 'Hyundai Creta 2018, segundo dueño, 76.000km, muy bien cuidada, cochera, cuatro gomas nuevas, auxilio sin rodar', '2026-08-19 09:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493492507068', 'Norberto', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta con oferta de financiación y toma de usado. Se envió imagen principal del Creta. Preguntó por planes de financiación; se le explicó que un asesor arma la propuesta personalizada. Cliente se identificó como Norberto, de Santa Fe (fuera de zona Norte). Pidió precio y ficha técnica; se derivó consulta de precio a un asesor. En este turno preguntó si podía ser atendido en Rosario o Buenos Aires por estar más cerca; se le aclaró que solo hay sucursal en Salta y que la atención sería remota (llamada/WhatsApp). Falta apellido, ciudad, versión elegida, y confirmación de que acepta la modalidad remota.', '2026-08-18T15:53:13.797317+00:00', '2026-08-18T18:56:01.088386+00:00', '', '', 'Otra', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493496541803', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta 0km con entrega inmediata. Se envió imagen principal del modelo. Falta capturar nombre y demás datos.', '2026-08-18T15:56:09.772444+00:00', '2026-08-18T15:56:09.772444+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492984135907', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Nueva Creta con oferta de toma de usado. Preguntó cómo funciona el proceso de cambio de su vehículo usado. Se le explicó que el asesor tasa el vehículo y arma propuesta personalizada. Se envió imagen principal de Creta. Falta capturar nombre, provincia y datos del vehículo a entregar.', '2026-08-19T20:45:56.048566+00:00', '2026-08-19T20:45:56.048566+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492317401124', 'Lorenzo', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram de la Nueva Hyundai Creta preguntando por el precio. Se envió imagen principal del modelo. Se le explicó que el precio exacto lo brinda un asesor comercial según versión y forma de pago. Cliente se identificó como Lorenzo, vive en 9 de Julio, Buenos Aires (provincia Otra, fuera de zona Norte). Lorenzo comentó que Salta le queda muy lejos; se le confirmó que puede ser atendido por llamada o mensaje desde Salta. Lorenzo confirmó que prefiere ser contactado por llamada. Pendiente: apellido, presupuesto, uso previsto, forma de pago, coordinar horario de la llamada.', '2026-08-16T10:45:31.546543+00:00', '2026-08-18T19:37:26.816314+00:00', '', '', 'Buenos Aires', '9 de Julio', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875068866', '', 'Cierre', 'Creta', '', NULL, 'Cliente consultó precio del New Creta y mencionó que tiene un vehículo usado para entregar en parte de pago. Se le explicó que el precio lo brinda un asesor y se coordinó contacto para mañana en horario comercial. Falta capturar nombre, provincia/ciudad, y detalle del vehículo en permuta.', '2026-08-19T21:56:05.780755+00:00', '2026-08-19T21:56:05.780755+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '2026-08-20 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491155911980', 'René', 'Cierre', 'Creta', '', NULL, 'Cliente (René) llegó por anuncio de la Nueva Hyundai Creta preguntando precio. Se envió imagen principal del modelo. René es de Pilar, Buenos Aires (provincia ''Otra'', fuera de zona Norte). La versión de interés es Safety +. Insistió con precio; se sostuvo la política de derivar a un asesor. Se le ofreció contacto desde Salta pero René rechazó explícitamente la derivación (''No gracias, deja nomás''). Falta calificar uso previsto, forma de pago. René respondió con un simple 👍, se cierra la charla dejando la puerta abierta para retomar cuando quiera.', '2026-08-19T11:45:46.478799+00:00', '2026-08-19T15:02:04.557615+00:00', '', '', 'Otra', 'Pilar', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491160507471', 'Niko', 'Desarrollada', 'Creta', '', NULL, 'Cliente (Niko) llegó por anuncio de Facebook/Instagram sobre la Nueva Hyundai Creta 0km con entrega inmediata y toma de usado. Se envió imagen principal del Creta. Confirmó que tiene un Hyundai i30 2014 GLS Premium 1.8 CVT con 180.000 km para entregar en parte de pago. Se le explicó que el valor de toma lo define un asesor al evaluar la unidad. Confirmó que está en Capital Federal (CABA), provincia ''Otra''. Aceptó ser atendido por llamada o mensaje desde Salta. Preguntó si su vehículo en permuta era relevante/aceptable, se le confirmó que sí. Respondió afirmativamente (''Si'') a continuar el proceso. Falta uso previsto, presupuesto, email y coordinar horario de contacto.', '2026-08-19T11:03:36.872212+00:00', '2026-08-19T14:17:44.115968+00:00', '', '', 'Otra', 'CABA', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', 'Hyundai i30 2014 GLS Premium 1.8 CVT, 180.000 km', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493772435819', 'Victor', 'Abierta', 'HB20S', '', NULL, 'Cliente Víctor, de Corrientes (fuera de zona Norte), interesado en HB20S para uso particular. Se le avisó que la atención sería remota desde Salta (llamada/mensaje). Mostró resistencia por la distancia y, al ofrecerle coordinar una llamada, rechazó explícitamente la propuesta (''No, gracias''). Queda abierta la puerta para retomar contacto más adelante si lo desea. Faltan presupuesto, ciudad y forma de pago.', '2026-08-18T21:37:07.324892+00:00', '2026-08-19T00:42:04.970386+00:00', '', '', 'Otra', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20Sedan-destacados-exterior-frente.jpg:principal', '', 'Particular', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493814747897', 'Bernabé', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la Hyundai Creta 0km con entrega inmediata, toma de usado y asesoramiento premium. Se le envió imagen principal y de interior de la Creta. Cliente prefiere comunicación por mensaje/WhatsApp porque está recién operado de la mandíbula y no puede hablar por teléfono. Nombre: Bernabé Garat. Busca un SUV automático, nafta, con buena capacidad de carga - la Creta Safety+ cumple. Es de San Miguel de Tucumán, atendido por mensaje desde Salta. Confirmó forma de pago: Financiado. Tiene un vehículo 2017 con 112.000 km para entregar en parte de pago. La cita previa quedó confirmada por WhatsApp para contacto del asesor. Cliente agradeció y cerró la conversación cordialmente, sin nueva información ni dudas pendientes.', '2026-08-18T17:04:15.446433+00:00', '2026-08-18T20:37:48.349006+00:00', '', 'Garat', 'Tucumán', 'San Miguel de Tucumán', 'Norte', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal, https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacioso-y-moderno.jpg:exterior_lateral, https://agnhyundai.com.ar/wp-content/uploads/2025/06/creta25-destacados-espacio-interior-1.jpg:interior', 'Safety +', 'Particular', 'Financiado', 'Prefiere contacto por mensaje/WhatsApp, no llamadas telefónicas, en cualquier momento', 'false', '', 'Vehículo 2017, 112.000 km, modelo sin especificar', '2026-08-18 17:36');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493513253835', '', 'Abierta', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram sobre la Nueva Hyundai Creta 0km con entrega inmediata, toma de usado y asesoramiento premium. Se envió imagen principal de Creta. Falta capturar nombre, provincia y demás datos.', '2026-08-19T00:32:40.615826+00:00', '2026-08-19T00:32:40.615826+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875105011', 'Paola', 'Cierre', 'HB20', '', NULL, 'Cliente (Paola) contactó preguntando por precio y financiación del HB20. Preguntó por versiones disponibles del HB20; se le listaron (Comfort Plus MT, Comfort Plus AT, Platinum Safety AT). Confirmó provincia Salta y ciudad Salta Capital. Se había coordinado llamada para el 19/08 a las 10:00, pero pasó sin contacto efectivo. Se reagendó para las 12:30 del mismo día. En este turno Paola confirmó que sigue esperando el contacto a las 12:30 (hora actual coincide, cita vigente). Se le reconfirmó la llamada y se le preguntó nuevamente por la versión elegida. Falta capturar apellido, uso previsto, forma de pago definitiva y versión elegida.', '2026-08-18T20:13:59.20448+00:00', '2026-08-19T15:07:05.865299+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', '', '', '', '', 'Mañana de 10 a 13hs', 'false', '', '', '2026-08-19 12:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493875393264', '', 'Abierta', '', '', NULL, 'Cliente llegó por anuncio general de AGN Hyundai (sin modelo específico mencionado). Se le preguntó el nombre para continuar la charla.', '2026-08-19T17:56:12.150893+00:00', '2026-08-19T17:56:12.150893+00:00', '', '', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491140541212', '', 'Desarrollada', 'Creta', '', NULL, 'Cliente llegó por anuncio de New Creta con oferta de toma de usado y financiación. Preguntó cómo funciona el cambio de su vehículo usado; se le explicó que se toma en parte de pago con tasación. Preguntó si el precio de U$S 27.500 era real; se aclaró que valores exactos los confirma un asesor. Preguntó por qué cambia el precio viendo la versión base; se explicó que depende de versión, equipamiento y forma de pago. Preguntó de qué concesionaria son; se le contó que es AGN Hyundai, oficial en Salta. Ahora indicó que es de Buenos Aires, por lo que se le aclaró que sería atendido por llamada/mensaje desde Salta, y se le preguntó si está de acuerdo. Falta registrar nombre, ciudad, y datos del vehículo a permutar.', '2026-08-19T14:23:05.901898+00:00', '2026-08-19T17:28:39.328272+00:00', '', '', 'Otra', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', 'Permuta', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5491149923016', '', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de la New Creta, preguntó por el precio. Se le explicó que el valor exacto lo da un asesor y se coordinó contacto para mañana desde las 9hs (fuera de horario de atención actual). Se le pidió nombre y ciudad, aún sin registrar.', '2026-08-19T20:02:30.678729+00:00', '2026-08-19T20:02:30.678729+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493446632448', 'Fabio', 'Cierre', 'Creta', '', NULL, 'Cliente Fabio llegó por anuncio de la Nueva Hyundai Creta, preguntó precio (se explicó que lo da un asesor). Se envió imagen principal del Creta. Confirmó contacto para mañana 20/08 desde las 9hs. Preguntó ubicación de la sucursal (Pellegrini 1030, Salta) y aclaró que está lejos, por lo que no puede visitarla presencialmente, pero mantiene el contacto telefónico acordado. Falta capturar apellido, provincia, ciudad y otros datos comerciales.', '2026-08-19T20:30:49.623352+00:00', '2026-08-19T23:34:13.751544+00:00', '', '', '', '', '', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', '', 'false', '', '', '2026-08-20 09:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874111001', 'Nicolas', 'Cierre', 'HB20', '', NULL, 'Cliente Nicolás llegó por anuncio general de AGN Hyundai. Mostró interés en el HB20 para uso familiar. Se le envió imagen principal del HB20. Confirmó Salta capital, habilitando visita presencial y prueba de manejo. Preguntó por financiación; se le explicó que un asesor arma el plan a medida. Ahora pidió que lo llamen porque trabaja casi todo el día, se le consulta franja horaria preferida para coordinar la llamada. Falta definir presupuesto, versión, forma de pago y horario exacto de contacto.', '2026-08-20T17:48:59.876688+00:00', '2026-08-20T21:09:42.820564+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', 'Particular', '', '', 'true', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5492615175227', 'Ignacio', 'Cierre', 'Creta', '', NULL, 'Cliente llegó por anuncio de Facebook/Instagram del New Creta, mencionando financiación y toma de usado. Se identificó como Ignacio López, está en Mendoza (fuera de zona Norte), aceptó ser atendido por llamada/mensaje desde Salta. Coordinó contacto hoy a las 17hs. Preguntó por versiones (Safety+ es la única disponible), su equipamiento de seguridad y precio (derivado al asesor). Ahora preguntó si tiene techo corredizo; se le informó que la versión Safety+ no lo incluye, y se reconfirmó el contacto de las 17hs.', '2026-08-20T14:37:12.76426+00:00', '2026-08-20T18:05:11.737221+00:00', '', 'López', 'Otra', '', 'Fuera de zona', 'Baja probabilidad de compra', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', 'Safety +', '', '', 'Más tarde, cuando sale del trabajo - hoy 17hs', 'false', '', '', '2026-08-20 17:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874828065', 'Pamela', 'Abierta', '', '', NULL, 'El cliente saludó por primera vez. Se le preguntó el nombre y respondió: Pamela Rojas. Aún no definió modelo de interés, presupuesto, ni otros datos.', '2026-08-21T09:55:58.611577+00:00', '2026-08-21T12:56:32.743977+00:00', '', 'Rojas', '', '', '', '', '', '', '', '', '', 'false', '', '', '');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874515017', 'Javier', 'Cierre', 'HB20', '', NULL, 'Cliente Javier, llegó por anuncio general de AGN Hyundai. Interesado en Hyundai HB20 para uso particular, forma de pago plan de ahorro. Confirmó que está en Salta Capital. Pidió que un asesor lo llame y propuso las 18:30hs de hoy como horario de contacto. Se registra esa hora para la llamada. Falta definir presupuesto y confirmar versión del HB20.', '2026-08-20T15:10:56.867922+00:00', '2026-08-20T18:42:32.730521+00:00', '', '', 'Salta', 'Salta Capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/07/Hyundai-HB20-destacados-exterior-frente.jpg:principal', '', 'Particular', 'Plan de ahorro', '18:30hs', 'false', '', '', '2026-08-20 18:30');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493874837774', 'Gladys', 'Cierre', 'Creta', '', NULL, 'Cliente Gladys Sosa, de Salta capital, llegó por anuncio de la Nueva Hyundai Creta preguntando precio. Se le explicó que el valor lo brinda un asesor. Había confirmado visita a la sucursal de Pellegrini 1030 el viernes 21/08 a las 15hs para conocer el Creta, pero avisó que por motivos laborales no podrá asistir. Se despidió agradeciendo la atención. Queda pendiente que ella se contacte nuevamente para coordinar nueva fecha, versión, uso previsto y forma de pago.', '2026-08-20T15:10:40.019074+00:00', '2026-08-21T17:57:48.783222+00:00', '', 'Sosa', 'Salta', 'Salta capital', 'Salta', '', 'https://agnhyundai.com.ar/wp-content/uploads/2025/06/3.jpg:principal', '', '', '', 'tarde', 'false', '', '', '2026-08-21 15:00');
INSERT INTO "hyundai-ventas"."agnMemory" VALUES ('5493815760221', 'Jose', 'Cierre', 'Tucson', '', NULL, 'El cliente José confirmó que su provincia es Tucumán y su ciudad es Burruyacu. Se le explicó que será atendido por llamada/mensaje desde Salta. Propuso que lo contacten mañana sábado a las 10hs, quedó registrado como horario de contacto acordado. Pendiente: presupuesto, forma de pago, uso previsto.', '2026-08-21T17:41:13.637252+00:00', '2026-08-21T20:45:17.043009+00:00', '', 'Prueba', 'Tucumán', 'Burruyacu', 'Norte', '', '', '', '', '', 'mañana a las 10hs', 'false', '', '', '2026-08-22 10:00');
INSERT INTO "hyundai-ventas".contenido_narrativo VALUES ('a66037b3-47a0-4582-9c32-f533289b1bc5', 'e31bb0d2-7f4d-4caa-b2a9-becf42a8fde0', 'Hyundai', 'argumento_venta', 'HB20 — seguridad como diferencial', 'Las 3 versiones incluyen 6 airbags de serie. La versión Platinum Safety suma el paquete ADAS completo: frenado autónomo de emergencia, asistente de mantenimiento de carril y alerta de tráfico cruzado trasero — un argumento fuerte para compradores con foco en seguridad familiar.', NULL, NULL, 'https://agnhyundai.com.ar/hb20/', NULL, NULL, 'true', '2026-07-13T14:43:56.710875+00:00', '2026-07-13T14:43:56.710875+00:00');
